        try:
            (WORK / 'registered_devices.json').write_bytes(_ORIGINAL_BYTES)
        except Exception:
            pass
    with open(LOGDIR / 'reward.txt', 'w') as f:
        f.write('1' if ok else '0')
    log(f"REWARD={'1' if ok else '0'} {reason}")
    sys.exit(0)


def expected_details(dev):
    return {'mac_address': GOOD[dev], 'device_id': dev}


