        return False, f'report is not a list (got {type(data).__name__})'
    if len(data) != len(allowed):
        return False, f'report has {len(data)} entries, expected {len(allowed)}'
    seen = set()
    for i, item in enumerate(data):
        if not isinstance(item, dict) or set(item) != {'details'}:
            keys = set(item) if isinstance(item, dict) else type(item).__name__
            return False, f'entry {i}: top-level keys are {keys}, must be exactly {{\'details\'}}'
        d = item['details']
        if not isinstance(d, dict):
            return False, f'entry {i}: "details" is not an object'
        if set(d) != {'mac_address', 'device_id'}:
            return False, f'entry {i}: "details" keys are {set(d)}, must be exactly ' \
                          f'{{\'mac_address\', \'device_id\'}}'
        dev = d['device_id']
        if dev not in allowed:
            return False, f'entry {i}: unexpected device_id {dev!r}'
        if dev in seen:
            return False, f'entry {i}: duplicate device_id {dev!r}'
        if d['mac_address'] != allowed[dev]:
            return False, f'entry {i}: mac_address {d["mac_address"]!r} for {dev} ' \
                          f'expected {allowed[dev]!r}'
        seen.add(dev)
    return True, 'ok'


