    ports = set()
    for f in ('/proc/net/tcp', '/proc/net/tcp6'):
        try:
            lines = Path(f).read_text().splitlines()[1:]
        except Exception:
            continue
        for ln in lines:
            p = ln.split()
            if len(p) > 3 and p[3] == '0A':
                try:
                    ports.add(int(p[1].split(':')[-1], 16))
                except Exception:
                    pass
    return ports


