    try:
        s = socket.create_connection(('127.0.0.1', port), timeout=timeout)
        s.close()
        return True
    except Exception:
        return False


def raw_concurrency_probe(port, n=10):
    """Return None if loopback connects all fail (port not reachable from here), else bool."""
    results = []
    lock = threading.Lock()

    def worker():
        try:
            s = socket.create_connection(('127.0.0.1', port), timeout=5)
            s.close()
            r = True
        except Exception:
            r = False
        with lock:
            results.append(r)

    th = [threading.Thread(target=worker, daemon=True) for _ in range(n)]
    for t in th:
        t.start()
    for t in th:
        t.join(10)
    ok = sum(1 for r in results if r)
    if ok == 0:
        return None
    return ok == n


def start_server(session):
    pre = listening_ports()
    logpath = LOGDIR / f'{session}_server.log'
    out = open(logpath, 'wb')
    proc = subprocess.Popen(
        [sys.executable, 'server.py'],
        cwd=WORK,
        stdin=subprocess.DEVNULL,
        stdout=out,
        stderr=subprocess.STDOUT,
        start_new_session=True,
    )
    port = None
    deadline = time.time() + 6
    while time.time() < deadline and port is None:
        time.sleep(0.3)
        for p in sorted(listening_ports() - pre):
            if try_connect(p, 1.5):
                port = p
                break
    return proc, port, out, logpath


def kill_proc(proc):
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    try:
        proc.wait(timeout=5)
    except Exception:
        pass


