    # after the 60 s master timeout: partial results saved
    now = time.time()
    if now < t0 + 60.5:
        time.sleep(t0 + 60.5 - now)
    data = None
    why = 'report file not found'
    deadline = t0 + 66
    while time.time() < deadline:
        if jsonp.exists():
            try:
                data = json.loads(jsonp.read_text(encoding='utf-8'))
                ok, why = validate_report(data, expected)
                if ok:
                    break
            except Exception as e:
                why = f'report not valid yet ({e})'
        time.sleep(0.5)
    if data is not None:
        record(f'{name}_report_after_timeout', validate_report(data, expected)[0], why)
    else:
        record(f'{name}_report_after_timeout', False, why)
    # master timeout: server must stop (and therefore stop listening)
    deadline = t0 + 70
    alive = True
    while time.time() < deadline:
        if proc.poll() is not None:
            alive = False
            break
        time.sleep(0.5)
    if alive:
        kill_proc(proc)
        record(f'{name}_server_stops_after_60s', False, 'still running at t+70s (killed)')
    else:
        record(f'{name}_server_stops_after_60s', True, f'exit code {proc.returncode}')
