        t.start()
    for t in th:
        t.join(10)
    ok = sum(1 for r in results if r)
    if ok == 0:
        return None
    return ok == n


def start_server(session):
    pre = listening_ports()
    logpath = LOGDIR / f'{session}_server.log'
    out = open(logpath, 'wb')
    proc = subprocess.Popen(
        [sys.executable, 'server.py'],
        cwd=WORK,
        stdin=subprocess.DEVNULL,
        stdout=out,
        stderr=subprocess.STDOUT,
        start_new_session=True,
    )
    port = None
    deadline = time.time() + 6
    while time.time() < deadline and port is None:
        time.sleep(0.3)
        for p in sorted(listening_ports() - pre):
            if try_connect(p, 1.5):
                port = p
                break
    return proc, port, out, logpath


def kill_proc(proc):
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    try:
        proc.wait(timeout=5)
    except Exception:
        pass


def run_device(session, script, arg):
    logpath = LOGDIR / f'{session}_{Path(script).stem}.log'
    out = open(logpath, 'wb')
    p = subprocess.Popen(
        [sys.executable, script, arg],
        cwd=WORK,
        stdin=subprocess.DEVNULL,
        stdout=out,
        stderr=subprocess.STDOUT,
    )
    try:
        p.wait(timeout=25)
        rc = p.returncode
    except subprocess.TimeoutExpired:
        p.kill()
        p.wait()
        rc = None
    out.close()
    return rc


def run_session(name, good_ids, run_faulty, expected, do_probe, do_error_check):
    jsonp = WORK / 'registered_devices.json'
    try:
        jsonp.unlink()
    except FileNotFoundError:
        pass
    t0 = time.time()
    proc, port, out, logpath = start_server(name)
    log(f'{name}: server pid={proc.pid} port={port}')
    if port is not None and do_probe:
        res = raw_concurrency_probe(port)
        if res is None:
            log(f'{name}: port {port} not reachable from loopback; skipping concurrency probe')
        else:
            record(f'{name}_accepts_10_simultaneous_connections', res,
                   'concurrency: 10 simultaneous connections')
    # the server must be alive during the session (a script that just writes a file and exits fails here)
    now = time.time()
    if now < t0 + 12:
        time.sleep(t0 + 12 - now)
    if proc.poll() is None:
        record(f'{name}_server_alive_during_session', True, 'alive at t+12s')
    else:
        record(f'{name}_server_alive_during_session', False,
               f'process already exited (rc={proc.returncode})')
        out.close()
        return False
    # good devices, concurrently
    if good_ids:
        ps = []
        for dev in good_ids:
            logpath = LOGDIR / f'{name}_{dev}.log'
            outd = open(logpath, 'wb')
            p = subprocess.Popen(
                [sys.executable, 'iot_device.py', dev],
                cwd=WORK, stdin=subprocess.DEVNULL, stdout=outd, stderr=subprocess.STDOUT)
            ps.append((dev, p, outd))
        for dev, p, outd in ps:
            try:
                p.wait(timeout=25)
            except subprocess.TimeoutExpired:
                p.kill()
                p.wait()
            outd.close()
        if proc.poll() is None:
            record(f'{name}_server_alive_after_good_devices', True, '')
        else:
            record(f'{name}_server_alive_after_good_devices', False,
                   f'server crashed (rc={proc.returncode})')
            out.close()
            return False
    if run_faulty:
        pre_size = logpath.stat().st_size
        run_device(name, 'iot_device_faulty.py', 'device-0003')
        if proc.poll() is None:
            record(f'{name}_server_survives_faulty_device', True, '')
        else:
            record(f'{name}_server_survives_faulty_device', False,
                   f'server crashed (rc={proc.returncode}) after faulty device')
            out.close()
            return False
        if do_error_check:
            time.sleep(0.5)
            try:
                with open(logpath, 'rb') as f:
                    f.seek(pre_size)
                    diff = f.read()
            except Exception as e:
                diff = b''
                log(f'{name}: could not read server log diff: {e}')
            record(f'{name}_logs_error_for_faulty_device',
                   re.search(rb'error|fail', diff, re.I) is not None,
                   f'server log after faulty registration: {diff[:400]!r}')
        if port is not None:
            record(f'{name}_server_still_accepts_after_faulty', try_connect(port, 3),
                   'server accepts new connections after faulty device')
    # after the 60 s master timeout: partial results saved
    now = time.time()
    if now < t0 + 60.5:
        time.sleep(t0 + 60.5 - now)
    data = None
    why = 'report file not found'
    deadline = t0 + 66
    while time.time() < deadline:
        if jsonp.exists():
            try:
                data = json.loads(jsonp.read_text(encoding='utf-8'))
                ok, why = validate_report(data, expected)
                if ok:
                    break
            except Exception as e:
                why = f'report not valid yet ({e})'
        time.sleep(0.5)
    if data is not None:
        record(f'{name}_report_after_timeout', validate_report(data, expected)[0], why)
    else:
        record(f'{name}_report_after_timeout', False, why)
    # master timeout: server must stop (and therefore stop listening)
    deadline = t0 + 70
    alive = True
    while time.time() < deadline:
        if proc.poll() is not None:
            alive = False
            break
        time.sleep(0.5)
    if alive:
        kill_proc(proc)
        record(f'{name}_server_stops_after_60s', False, 'still running at t+70s (killed)')
    else:
        record(f'{name}_server_stops_after_60s', True, f'exit code {proc.returncode}')
    if port is not None:
        time.sleep(1)
        record(f'{name}_port_closed_after_timeout', not try_connect(port, 2),
               'port no longer accepts connections')
    try:
        out.close()
    except Exception:
        pass
    return True
